#!/usr/bin/env python3
"""Helpers for the backup, release and restore workflows (plan 2026-10-27-beta-betrieb).

Only counts and table names are ever printed: the repository is public, so logs must never
contain rows, nicknames or connection strings.

  db_tools.py counts DATA_SQL            -> JSON {"schema.table": rows} of a data-only dump
  db_tools.py truncate-sql DATA_SQL      -> SQL that empties exactly the tables of the dump
  db_tools.py load-sql DATA_SQL OUT      -> the dump without storage and migration histories
  db_tools.py check DATA_SQL LIVE_JSON   -> compares dump counts with live counts, exit 1 on a problem
  db_tools.py summary DATA_SQL [LIVE]    -> Markdown table for $GITHUB_STEP_SUMMARY
"""
import json
import re
import sys

COPY_RE = re.compile(r'^COPY "([^"]+)"\."([^"]+)"')
# Tables the restore must not touch: storage internals and both migration histories (the target
# keeps its own schema version, also that of the auth service).
SKIP_SCHEMAS = {"storage", "supabase_migrations"}
SKIP_TABLES = {"auth.schema_migrations"}


# Tables that must be in every backup and must not be empty.
REQUIRED = ["auth.users", "public.profiles", "public.classes"]
# Rows may change between dump and count (a pupil solving a quest); a small drift is fine.
TOLERANCE = 5


def restorable(table):
    return table.split(".")[0] not in SKIP_SCHEMAS and table not in SKIP_TABLES


def counts(path):
    result = {}
    current = None
    with open(path, encoding="utf-8", errors="replace") as fh:
        for line in fh:
            if current is None:
                m = COPY_RE.match(line)
                if m:
                    current = f"{m.group(1)}.{m.group(2)}"
                    result[current] = 0
            elif line.startswith("\\."):
                current = None
            else:
                result[current] += 1
    return result


def truncate_sql(path):
    tables = [t for t in counts(path) if restorable(t)]
    quoted = ", ".join('"{}"."{}"'.format(*t.split(".", 1)) for t in tables)
    return (
        "-- generated by db_tools.py: empty exactly the tables of the backup, then load it\n"
        "SET session_replication_role = replica;\n"
        f"TRUNCATE {quoted};\n"
    )


def check(path, live_path):
    dump = counts(path)
    with open(live_path, encoding="utf-8") as fh:
        live = json.load(fh)
    problems = []
    for table in REQUIRED:
        if dump.get(table, 0) == 0:
            problems.append(f"{table}: fehlt in der Sicherung oder ist leer")
    for table, n in live.items():
        if table not in dump:
            problems.append(f"{table}: fehlt in der Sicherung")
        elif abs(dump[table] - n) > TOLERANCE:
            problems.append(f"{table}: Sicherung {dump[table]}, live {n}")
    for p in problems:
        print(f"::error::{p}")
    return 1 if problems else 0


def load_sql(path, out_path):
    """The data dump without the tables the restore must not touch."""
    out, skip = [], False
    with open(path, encoding="utf-8", errors="replace") as fh:
        for line in fh:
            m = COPY_RE.match(line)
            if m and not restorable(f"{m.group(1)}.{m.group(2)}"):
                skip = True
            if not skip:
                out.append(line)
            elif line.startswith("\\."):
                skip = False
    with open(out_path, "w", encoding="utf-8") as fh:
        fh.writelines(out)


def summary(path, live_path=None):
    dump = counts(path)
    live = {}
    if live_path:
        with open(live_path, encoding="utf-8") as fh:
            live = json.load(fh)
    rows = ["| Tabelle | Zeilen in der Sicherung | Zeilen live |", "|---|---:|---:|"]
    for table in sorted(set(REQUIRED) | set(live)):
        rows.append(f"| `{table}` | {dump.get(table, '–')} | {live.get(table, '–')} |")
    rows.append(f"\n{len(dump)} Tabellen, {sum(dump.values())} Zeilen insgesamt.")
    return "\n".join(rows)


def main(argv):
    if len(argv) >= 2 and argv[0] == "counts":
        print(json.dumps(counts(argv[1]), sort_keys=True))
        return 0
    if len(argv) >= 2 and argv[0] == "truncate-sql":
        sys.stdout.write(truncate_sql(argv[1]))
        return 0
    if len(argv) >= 3 and argv[0] == "load-sql":
        load_sql(argv[1], argv[2])
        return 0
    if len(argv) >= 3 and argv[0] == "check":
        return check(argv[1], argv[2])
    if len(argv) >= 2 and argv[0] == "summary":
        print(summary(argv[1], argv[2] if len(argv) > 2 else None))
        return 0
    print(__doc__)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
